239.     ///
240.     /// # Description
241.     ///
242.     /// Frees a frame that was previously allocated.
243.     ///
244.     /// # Parameters
245.     ///
246.     /// - `frame`: Address of the frame to free.
247.     ///
248.     /// # Returns
249.     ///
250.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
251.     ///
252.     #[verus_spec(result =>
253.         requires
254.             old(self).inv(),
255.             frame.inv(),
256.         ensures
257.             final(self).inv(),
258.             match result {
259.                 Ok(()) => {
260.                     &&& old(self)@.allocated_frames.contains(frame@)
261.                     &&& old(self)@.refcounts.contains_key(frame@)
262.                     &&& old(self)@.refcounts[frame@] > 0
263.                     &&& if old(self)@.refcounts[frame@] == 1 {
264.                         // Last reference: release frame
265.                         final(self)@ == FrameAllocView {
266.                             allocated_frames: old(self)@.allocated_frames.remove(frame@),
267.                             free_frames: old(self)@.free_frames.insert(frame@),
268.                             refcounts: old(self)@.refcounts.remove(frame@),
269.                         }
270.                     } else {
271.                         // Still shared: decrement refcount
272.                         final(self)@ == FrameAllocView {
273.                             allocated_frames: old(self)@.allocated_frames,
274.                             free_frames: old(self)@.free_frames,
275.                             refcounts: old(self)@.refcounts.insert(
276.                                 frame@, old(self)@.refcounts[frame@] - 1
277.                             ),
278.                         }
279.                     }
280.                 },
281.                 Err(_) => {
282.                     &&& final(self)@ == old(self)@
283.                     &&& !old(self)@.allocated_frames.contains(frame@)
284.                 }
285.             },
286.     )]
287.     fn free(&mut self, frame: FrameAddress) -> Result<(), Error> {
288.         let frame_number: usize = frame.into_frame_number().into_raw_value();
289. 
290.         if frame_number >= self.refcount.len() {
291.             let reason: &str = "frame number out of bounds";
292.             error!("{reason} (frame={frame:?})");
293.             return Err(Error::new(ErrorCode::BadAddress, reason));
294.         }
295. 
296.         // Reject double-frees: the frame must currently have at least one owner.
297.         if self.refcount[frame_number] == 0 {
298.             let reason: &str = "frame is already free";
299.             error!("{reason} (frame={frame:?})");
300.             return Err(Error::new(ErrorCode::BadAddress, reason));
301.         }
302. 
303.         self.refcount[frame_number] -= 1;
304. 
305.         // Only release the bit in the bitmap when the last owner releases the frame.
306.         if self.refcount[frame_number] == 0 {
307.             match self.bitmap.clear(frame_number) {
308.                 Ok(()) => Ok(()),
309.                 Err(error) => {
310.                     error!("{error:?} (frame={frame:?})");
